package tokenizer

import java.nio.charset.Charset
import java.time.format.DateTimeFormatter
import java.time.{LocalDate, LocalDateTime}
import java.util.Locale

import io.circe.Json

import scala.collection.mutable

// ============================================================================
// Protocol-like traits
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value: String = "string" }
  case object NUMERIC extends TokenType { val value: String = "numeric" }
  case object TEMPORAL extends TokenType { val value: String = "temporal" }
  case object STRUCTURED extends TokenType { val value: String = "structured" }
  case object BINARY extends TokenType { val value: String = "binary" }
  case object NULL extends TokenType { val value: String = "null" }

  val values: Vector[TokenType] = Vector(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)
}

// ============================================================================
// Core token classes
// ============================================================================

final case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(entries: (String, Any)*): Token = copy(metadata = metadata ++ entries)
}

final class MutableTokenBatch {
  private val buffer = mutable.ListBuffer.empty[Token]
  private var processed = false

  def tokens: List[Token] = buffer.toList

  def add(token: Token): Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }
}

// ============================================================================
// Generic container classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val data: Vector[T] = items.toVector

  def getAll: Vector[T] = data

  def mapTokens(func: T => String): List[String] = data.map(func).toList

  def size: Int = data.size
}

final class TokenSink[-T] {
  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val out = received.toList
    received.clear()
    out
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer base
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = values.iterator.map(tokenize)

  // Python compatibility alias
  def tokenize_batch(values: Iterable[T]): Iterator[Token] = tokenizeBatch(values)
}

// ============================================================================
// String tokenizer
// ============================================================================

final class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  private val charset = Charset.forName(encoding)

  def tokenize(value: String): Token = Token(normalizer(value), TokenType.STRING)

  def tokenize(value: Array[Byte]): Token = {
    val strValue = new String(value, charset)
    Token(normalizer(strValue), TokenType.STRING)
  }

  override def tokenize(value: Either[String, Array[Byte]]): Token = value match {
    case Left(str) => tokenize(str)
    case Right(bytes) => tokenize(bytes)
  }
}

// ============================================================================
// Numeric tokenizer
// ============================================================================

final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  private val formatString = s"%.${precision}f"

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal => bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case d: Double => String.format(Locale.ROOT, formatString, Double.box(d))
      case f: Float => String.format(Locale.ROOT, formatString, Float.box(f))
      case n: java.lang.Number => n.toString
      case other => other.toString
    }

    val originalType = Option(value).map(_.getClass.getSimpleName).getOrElse("null")
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType) ++ formatOptions)
